{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'fs'

// Parse command line arguments
const args = process.argv.slice(2)

if (args.length < 1 || args.length > 2) {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
  process.exit(2)
}

const mode = args[0]

if (mode === 'pack') {
  if (args.length !== 2) {
    process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
    process.exit(2)
  }

  const workers = args[1]
  if (!/^\d+$/.test(workers) || workers === '0' || workers[0] === '0') {
    process.stderr.write('error: workers must be a positive integer\n')
    process.exit(2)
  }
} else if (mode !== 'waves' && mode !== 'explain') {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
  process.exit(2)
}

// Read input from stdin
let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch (e) {
  // stdin might not be available in test, just use empty
}

// Parse the input
const lines = input.split('\n')
const tasks = new Map()
const deps = new Map()
let lineNum = 0
let errorOccurred = false

for (const line of lines) {
  lineNum++

  // Trim and skip empty lines and comments
  const trimmed = line.trim()
  if (trimmed === '' || trimmed[0] === '#') {
    continue
  }

  // Split on whitespace
  const words = trimmed.split(/\s+/)
  const directive = words[0]

  if (directive === 'task') {
    if (words.length !== 3) {
      process.stderr.write(`error: line ${lineNum}: expected task <name> <cost>\n`)
      process.exit(2)
    }

    const name = words[1]
    const costStr = words[2]

    // Validate task name
    if (!/^[A-Za-z0-9_.\-]+$/.test(name)) {
      process.stderr.write(`error: line ${lineNum}: invalid task name ${name}\n`)
      process.exit(2)
    }

    // Validate cost
    if (!/^\d+$/.test(costStr)) {
      process.stderr.write(`error: line ${lineNum}: cost must be a non-negative integer\n`)
      process.exit(2)
    }

    const cost = parseInt(costStr, 10)

    // Check for duplicate declaration
    if (tasks.has(name)) {
      process.stderr.write(`error: line ${lineNum}: task ${name} is declared twice\n`)
      process.exit(2)
    }

    tasks.set(name, { name, cost, dependencies: [] })
    if (!deps.has(name)) {
      deps.set(name, [])
    }
  } else if (directive === 'dep') {
    if (words.length < 2) {
      process.stderr.write(`error: line ${lineNum}: expected dep <name> <dependency>...\n`)
      process.exit(2)
    }

    const taskName = words[0]
    const depNames = words.slice(1)

    // Initialize if needed
    if (!deps.has(taskName)) {
      deps.set(taskName, [])
    }

    for (const depName of depNames) {
      // Add to deps, avoiding duplicates
      const depList = deps.get(taskName)
      if (!depList.includes(depName)) {
        depList.push(depName)
      }
    }
  } else {
    process.stderr.write(`error: line ${lineNum}: unknown directive ${directive}\n`)
    process.exit(2)
  }
}

// Update task dependencies from deps map
for (const [taskName, depList] of deps.entries()) {
  if (tasks.has(taskName)) {
    tasks.get(taskName).dependencies = depList
  }
}

// Check that all referenced tasks exist
for (const [taskName, depList] of deps.entries()) {
  for (const depName of depList) {
    if (!tasks.has(depName)) {
      process.stderr.write(`error: unknown task ${depName}\n`)
      process.exit(2)
    }
  }
}

// Check for cycles
function detectCycle() {
  const visited = new Set()
  const recursionStack = []
  const stackSet = new Set()

  function dfs(taskName) {
    if (stackSet.has(taskName)) {
      // Found a cycle
      const cycleStart = recursionStack.indexOf(taskName)
      const cycle = recursionStack.slice(cycleStart).concat(taskName)
      return cycle
    }

    if (visited.has(taskName)) {
      return null
    }

    visited.add(taskName)
    recursionStack.push(taskName)
    stackSet.add(taskName)

    const depList = deps.get(taskName) || []
    for (const depName of depList) {
      const cycle = dfs(depName)
      if (cycle) {
        return cycle
      }
    }

    recursionStack.pop()
    stackSet.delete(taskName)
    return null
  }

  // Check all tasks in ascending order
  const sortedTasks = Array.from(tasks.keys()).sort()
  for (const taskName of sortedTasks) {
    visited.clear()
    recursionStack.length = 0
    stackSet.clear()

    const cycle = dfs(taskName)
    if (cycle) {
      return cycle
    }
  }

  return null
}

const cycle = detectCycle()
if (cycle) {
  const cycleStr = cycle.join(' -> ')
  process.stderr.write(`error: cycle: ${cycleStr}\n`)
  process.exit(3)
}

// Compute wave/depth for each task
function computeDepths() {
  const depths = new Map()

  function getDepth(taskName) {
    if (depths.has(taskName)) {
      return depths.get(taskName)
    }

    const depList = deps.get(taskName) || []
    let maxDepth = 0
    for (const depName of depList) {
      maxDepth = Math.max(maxDepth, getDepth(depName) + 1)
    }

    depths.set(taskName, maxDepth)
    return maxDepth
  }

  for (const taskName of tasks.keys()) {
    getDepth(taskName)
  }

  return depths
}

const depths = computeDepths()

// Compute start/finish times
function computeSchedule() {
  const startTimes = new Map()
  const finishTimes = new Map()

  function getFinish(taskName) {
    if (finishTimes.has(taskName)) {
      return finishTimes.get(taskName)
    }

    const task = tasks.get(taskName)
    const depList = deps.get(taskName) || []

    let maxFinish = 0
    for (const depName of depList) {
      maxFinish = Math.max(maxFinish, getFinish(depName))
    }

    const start = maxFinish
    const finish = start + task.cost

    startTimes.set(taskName, start)
    finishTimes.set(taskName, finish)

    return finish
  }

  for (const taskName of tasks.keys()) {
    getFinish(taskName)
  }

  return { startTimes, finishTimes }
}

const { startTimes, finishTimes } = computeSchedule()

// Handle different modes
if (mode === 'waves') {
  const waveMap = new Map()
  for (const [taskName, depth] of depths.entries()) {
    if (!waveMap.has(depth)) {
      waveMap.set(depth, [])
    }
    waveMap.get(depth).push(taskName)
  }

  // Sort each wave and output
  const maxWave = tasks.size === 0 ? -1 : Math.max(...depths.values())
  for (let i = 0; i <= maxWave; i++) {
    const wave = waveMap.get(i) || []
    wave.sort()
    process.stdout.write(`wave ${i}: ${wave.join(' ')}\n`)
  }

  const maxFinish = tasks.size === 0 ? 0 : Math.max(...finishTimes.values())
  process.stdout.write(`total ${maxFinish}\n`)
} else if (mode === 'explain') {
  const sortedTasks = Array.from(tasks.keys()).sort()
  for (const taskName of sortedTasks) {
    const start = startTimes.get(taskName)
    const finish = finishTimes.get(taskName)
    const depth = depths.get(taskName)
    process.stdout.write(`${taskName} start=${start} finish=${finish} depth=${depth}\n`)
  }

  const maxFinish = tasks.size === 0 ? 0 : Math.max(...finishTimes.values())
  process.stdout.write(`total ${maxFinish}\n`)
} else if (mode === 'pack') {
  const workerCount = parseInt(args[1], 10)
  const workers = Array(workerCount).fill(null).map((_, i) => ({
    id: i,
    freeAt: 0,
    tasks: []
  }))

  // Compute priority for each task (longest chain starting from it)
  function computePriorities() {
    const priorities = new Map()

    function getPriority(taskName) {
      if (priorities.has(taskName)) {
        return priorities.get(taskName)
      }

      const task = tasks.get(taskName)
      let maxDepChain = task.cost

      // Find all tasks that depend on this one (in reverse)
      for (const [otherName, _] of tasks.entries()) {
        if (otherName === taskName) continue
        // Check if otherName depends (directly or indirectly) on taskName
        function dependsOn(a, b) {
          const visited = new Set()
          function check(name) {
            if (visited.has(name)) return false
            visited.add(name)
            const depList = deps.get(name) || []
            if (depList.includes(b)) return true
            for (const dep of depList) {
              if (check(dep)) return true
            }
            return false
          }
          return check(a)
        }

        if (dependsOn(otherName, taskName)) {
          maxDepChain = Math.max(maxDepChain, task.cost + getPriority(otherName))
        }
      }

      priorities.set(taskName, maxDepChain)
      return maxDepChain
    }

    for (const taskName of tasks.keys()) {
      getPriority(taskName)
    }

    return priorities
  }

  const priorities = computePriorities()

  // Check which tasks are finished
  const finished = new Set()

  // Simulate scheduling
  while (finished.size < tasks.size) {
    // Find ready tasks
    const ready = []
    for (const [taskName, task] of tasks.entries()) {
      if (finished.has(taskName)) continue

      // Check if all dependencies are finished
      const depList = deps.get(taskName) || []
      const allFinished = depList.every(dep => finished.has(dep))

      if (allFinished) {
        ready.push(taskName)
      }
    }

    if (ready.length === 0) {
      // No ready tasks, shouldn't happen if graph is valid
      break
    }

    // Sort by priority (descending), then by name (ascending)
    ready.sort((a, b) => {
      const priA = priorities.get(a)
      const priB = priorities.get(b)
      if (priA !== priB) {
        return priB - priA
      }
      return a.localeCompare(b)
    })

    // Assign to workers
    for (const taskName of ready) {
      // Find worker with earliest free time, by smallest index
      let bestWorker = workers[0]
      for (const worker of workers) {
        if (worker.freeAt < bestWorker.freeAt) {
          bestWorker = worker
        }
      }

      const task = tasks.get(taskName)
      const start = bestWorker.freeAt
      const finish = start + task.cost

      bestWorker.tasks.push({ name: taskName, start, finish })
      bestWorker.freeAt = finish
      finished.add(taskName)
    }
  }

  // Output results
  let maxFinish = 0
  for (const worker of workers) {
    let line = `worker ${worker.id}:`
    for (const task of worker.tasks) {
      line += ` ${task.name}@${task.start}-${task.finish}`
      maxFinish = Math.max(maxFinish, task.finish)
    }
    process.stdout.write(line + '\n')
  }

  process.stdout.write(`makespan ${maxFinish}\n`)
}
"}

