const input = 'task a 3\ntask b 2\ntask c 4\ntask d 1\ndep b a\ndep c a\ndep d b c\n'

const tasks = new Map()
const taskDeps = new Map()

const lines = input.split('\n')
for (const line of lines) {
  const trimmed = line.trim()
  if (!trimmed || trimmed[0] === '#') continue

  const words = trimmed.split(/\s+/)
  if (words[0] === 'task') {
    const name = words[1]
    const cost = parseInt(words[2])
    tasks.set(name, cost)
    if (!taskDeps.has(name)) taskDeps.set(name, [])
  } else if (words[0] === 'dep') {
    const taskName = words[1]
    const depNames = words.slice(2)
    if (!taskDeps.has(taskName)) taskDeps.set(taskName, [])
    for (const depName of depNames) {
      if (!taskDeps.get(taskName).includes(depName)) {
        taskDeps.get(taskName).push(depName)
      }
    }
  }
}

console.log('taskDeps:', taskDeps)

const workers = [{id: 0, freeAt: 0, tasks: []}, {id: 1, freeAt: 0, tasks: []}]
const scheduled = new Map()

let currentTime = 0
let iteration = 0

while (scheduled.size < tasks.size && iteration < 10) {
  iteration++
  console.log(`\n=== Iteration ${iteration}, time=${currentTime} ===`)

  const freeWorkers = workers.filter(w => w.freeAt <= currentTime).sort((a, b) => a.id - b.id)
  console.log(`Free workers:`, freeWorkers.map(w => `${w.id}(free@${w.freeAt})`))

  if (freeWorkers.length === 0) {
    currentTime = Math.min(...workers.map(w => w.freeAt))
    console.log(`No free workers, advancing to ${currentTime}`)
    continue
  }

  const ready = []
  for (const [taskName, _] of tasks.entries()) {
    if (scheduled.has(taskName)) continue

    const depList = taskDeps.get(taskName) || []
    const allFinished = depList.every(dep => {
      const depScheduled = scheduled.get(dep)
      const depFinished = depScheduled && depScheduled.finish <= currentTime
      console.log(`  ${taskName} dep ${dep}: scheduled=${!!depScheduled}, finish=${depScheduled?.finish}, ready=${depFinished}`)
      return depFinished
    })

    console.log(`  ${taskName}: ready=${allFinished}`)
    if (allFinished) {
      ready.push(taskName)
    }
  }

  console.log(`Ready tasks:`, ready)

  if (ready.length === 0) {
    console.log(`No ready tasks`)
    break
  }

  for (let i = 0; i < freeWorkers.length && i < ready.length; i++) {
    const worker = freeWorkers[i]
    const taskName = ready[i]
    const cost = tasks.get(taskName)
    const start = worker.freeAt
    const finish = start + cost

    console.log(`Assigning ${taskName} to worker ${worker.id}: ${start}-${finish}`)
    worker.tasks.push({name: taskName, start, finish})
    worker.freeAt = finish
    scheduled.set(taskName, {start, finish})
  }

  // Time advancement
  let anyZeroCost = false
  for (let i = 0; i < freeWorkers.length && i < ready.length; i++) {
    if (tasks.get(ready[i]) === 0) {
      anyZeroCost = true
      break
    }
  }

  if (!anyZeroCost) {
    currentTime = Math.min(...workers.map(w => w.freeAt))
    console.log(`No zero-cost tasks, advancing to ${currentTime}`)
  } else {
    console.log(`Zero-cost task assigned, staying at ${currentTime}`)
  }
}

console.log('\nFinal schedule:')
for (const worker of workers) {
  console.log(`worker ${worker.id}:`, worker.tasks.map(t => `${t.name}@${t.start}-${t.finish}`).join(' '))
}
EOF
